function cuaDescriptorPaths(platform, userData, home) {
  if (userData) return [join101(userData, "cua-connection.json")];
  if (platform !== "darwin") return [];
  return ["Origin", "OpenMausBot", "openmausbot", "OpenGrokBot", "opengrokbot"].map(
    (directory) => join101(home, "Library", "Application Support", directory, "cua-connection.json")
  );
}

